"""Deep semantic map of FMZ JavaScript strategy 数字货币期货交易类库测试版.md.

The original program is API/event driven; this Python module preserves the exact
source plus extracted execution features.  Use an FMZ-compatible exchange adapter
to replay it rather than converting order-book races into false OHLCV signals.
"""
SOURCE_FILE = '数字货币期货交易类库测试版.md'
SOURCE_FEATURES = ['var ', 'for ', 'while ', 'exchange.', '_C(', 'Sleep(', 'GetTicker']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.', 'Uses ticker/depth data; OHLCV-only backtests cannot reproduce microstructure fills exactly.']
ORIGINAL_JAVASCRIPT = '// 参数\n/*\nvar MinAmount = 1\nvar SlidePrice = 5\nvar Interval = 500\n*/\n\nfunction GetPosition(e, contractType, direction) {\n    e.SetContractType(contractType)\n    var positions = _C(e.GetPosition);\n    for (var i = 0; i < positions.length; i++) {\n        if (positions[i].ContractType == contractType && positions[i].Type == direction) {\n            return positions[i]\n        }\n    }\n\n    return null\n}\n\nfunction Open(e, contractType, direction, opAmount) {\n    var initPosition = GetPosition(e, contractType, direction);\n    var isFirst = true;\n    var initAmount = initPosition ? initPosition.Amount : 0;\n    var nowPosition = initPosition;\n    var directBreak = false \n    var preNeedOpen = 0\n    var timeoutCount = 0\n    while (true) {\n        var ticker = _C(e.GetTicker)\n        var needOpen = opAmount;\n        if (isFirst) {\n            isFirst = false;\n        } else {\n            nowPosition = GetPosition(e, contractType, direction);\n            if (nowPosition) {\n                needOpen = opAmount - (nowPosition.Amount - initAmount);\n            }\n            // 检测directBreak 并且持仓未变的情况\n            if (preNeedOpen == needOpen && directBreak) {\n                Log("疑似仓位数据延迟，等待30秒", "#FF0000")\n                Sleep(30000)\n                nowPosition = GetPosition(e, contractType, direction);\n                if (nowPosition) {\n                    needOpen = opAmount - (nowPosition.Amount - initAmount);\n                }\n                /*\n                timeoutCount++\n                if (timeoutCount > 10) {\n                    Log("连续10次疑似仓位延迟，下单失败！", "#FF0000")\n                    break\n                }\n                */\n            } else {\n                timeoutCount = 0\n            }\n        }\n        if (needOpen < MinAmount) {\n            break;\n        }\n        \n        var amount = needOpen;\n        preNeedOpen = needOpen\n        e.SetDirection(direction == PD_LONG ? "buy" : "sell");\n        var orderId;\n        if (direction == PD_LONG) {\n            orderId = e.Buy(ticker.Sell + SlidePrice, amount, "开多仓", contractType, ticker);\n        } else {\n            orderId = e.Sell(ticker.Buy - SlidePrice, amount, "开空仓", contractType, ticker);\n        }\n\n        directBreak = false\n        var n = 0\n        while (true) {\n            Sleep(Interval);\n            var orders = _C(e.GetOrders);\n            if (orders.length == 0) {\n                if (n == 0) {\n                    directBreak = true\n                }\n                break;\n            }\n            for (var j = 0; j < orders.length; j++) {\n                e.CancelOrder(orders[j].Id);\n                if (j < (orders.length - 1)) {\n                    Sleep(Interval);\n                }\n            }\n            n++\n        }\n    }\n\n    var ret = {\n        price: 0,\n        amount: 0,\n        position: nowPosition\n    };\n    if (!nowPosition) {\n        return ret;\n    }\n    if (!initPosition) {\n        ret.price = nowPosition.Price;\n        ret.amount = nowPosition.Amount;\n    } else {\n        ret.amount = nowPosition.Amount - initPosition.Amount;\n        ret.price = _N(((nowPosition.Price * nowPosition.Amount) - (initPosition.Price * initPosition.Amount)) / ret.amount);\n    }\n    return ret;\n}\n\nfunction Cover(e, contractType, opAmount, direction) {\n    var initPosition = null;\n    var position = null;\n    var isFirst = true;\n\n    while (true) {\n        while (true) {\n            Sleep(Interval);\n            var orders = _C(e.GetOrders);\n            if (orders.length == 0) {\n                break;\n            }\n            for (var j = 0; j < orders.length; j++) {\n                e.CancelOrder(orders[j].Id);\n                if (j < (orders.length - 1)) {\n                    Sleep(Interval);\n                }\n            }\n        }\n\n        position = GetPosition(e, contractType, direction)\n        if (!position) {\n            break\n        }\n        if (isFirst == true) {\n            initPosition = position;\n            opAmount = Math.min(opAmount, initPosition.Amount)\n            isFirst = false;\n        }\n\n        var amount = opAmount - (initPosition.Amount - position.Amount)\n        if (amount <= 0) {\n            break\n        }\n\n        var ticker = _C(e.GetTicker)\n        if (position.Type == PD_LONG) {\n            e.SetDirection("closebuy");\n            e.Sell(ticker.Buy - SlidePrice, amount, "平多仓", contractType, ticker);\n        } else if (position.Type == PD_SHORT) {\n            e.SetDirection("closesell");\n            e.Buy(ticker.Sell + SlidePrice, amount, "平空仓", contractType, ticker);\n        }\n\n        Sleep(Interval)\n    }\n\n    return position\n}\n\n$.OpenLong = function(e, contractType, amount) {\n    if (typeof(e) == "string") {\n        amount = contractType\n        contractType = e\n        e = exchange\n    }\n\n    return Open(e, contractType, PD_LONG, amount);\n}\n\n$.OpenShort = function(e, contractType, amount) {\n    if (typeof(e) == "string") {\n        amount = contractType\n        contractType = e\n        e = exchange\n    }\n\n    return Open(e, contractType, PD_SHORT, amount);\n};\n\n$.CoverLong = function(e, contractType, amount) {\n    if (typeof(e) == "string") {\n        amount = contractType\n        contractType = e\n        e = exchange\n    }\n\n    return Cover(e, contractType, amount, PD_LONG);\n};\n\n$.CoverShort = function(e, contractType, amount) {\n    if (typeof(e) == "string") {\n        amount = contractType\n        contractType = e\n        e = exchange\n    }\n\n    return Cover(e, contractType, amount, PD_SHORT);\n};\n\n\nfunction main() {\n    Log(exchange.GetPosition())\n    var info = $.OpenLong(exchange, "quarter", 100)\n    Log(info, "#FF0000")\n\n    Log(exchange.GetPosition())\n    info = $.CoverLong(exchange, "quarter", 30)\n    Log(exchange.GetPosition())\n    Log(info, "#FF0000")\n\n    info = $.CoverLong(exchange, "quarter", 80)\n    Log(exchange.GetPosition())\n    Log(info, "#FF0000")\n}'

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
